import axios from "axios";

/**
 * Builds the app's axios instance: cookie-authenticated JSON against a single
 * API base, with a 401 interceptor that bounces the browser to the sign-in
 * page instead of letting every caller handle expiry itself.
 *
 * Each app creates exactly one of these and re-exports it, so call sites keep
 * importing their own `api/client` module rather than the package.
 *
 * Options:
 *   baseURL        — API root (default "/api")
 *   withCredentials — send cookies (default true)
 *   headers        — merged over the default JSON content type
 *   loginPath      — where a 401 redirects to (default "/login")
 *   publicPaths    — routes that must NOT redirect on 401, because they are
 *                    where an unauthenticated user is supposed to be
 *                    (default: [loginPath])
 *   onUnauthorized — takes over the 401 handling entirely when supplied;
 *                    receives the axios error. No redirect happens.
 */
export function createApiClient({
  baseURL = "/api",
  withCredentials = true,
  headers,
  loginPath = "/login",
  publicPaths,
  onUnauthorized,
} = {}) {
  const publics = publicPaths ?? [loginPath];

  const api = axios.create({
    baseURL,
    withCredentials,
    headers: {
      "Content-Type": "application/json",
      ...headers,
    },
  });

  api.interceptors.response.use(
    (res) => res,
    (err) => {
      if (err.response?.status === 401) {
        if (onUnauthorized) {
          onUnauthorized(err);
        } else if (!publics.includes(window.location.pathname)) {
          window.location.href = loginPath;
        }
      }
      return Promise.reject(err);
    }
  );

  return api;
}
