import { createContext, useState, useEffect, useCallback, useMemo } from 'react';

export const AuthContext = createContext();

const initialStatus = {
  loading: true,
  isAuthenticated: false,
  needsSetup: false,
  username: null,
  role: null,
};

/**
 * Session state for a Common.Framework-style cookie auth backend.
 *
 * The axios instance is injected rather than imported, so the package never
 * owns the app's API configuration: <AuthProvider api={api}>.
 *
 *   api       — the app's axios client (required)
 *   basePath  — auth controller route prefix (default "/auth")
 *   adminRole — role name that flips isAdmin (default "Admin")
 */
export function AuthProvider({ children, api, basePath = '/auth', adminRole = 'Admin' }) {
  const [status, setStatus] = useState(initialStatus);

  const refresh = useCallback(() => (
    api.get(`${basePath}/status`)
      .then(res => setStatus({ ...res.data, loading: false }))
      .catch(() => setStatus({ ...initialStatus, loading: false }))
  ), [api, basePath]);

  useEffect(() => { refresh(); }, [refresh]);

  const value = useMemo(() => {
    const submit = async (route, username, password) => {
      const res = await api.post(`${basePath}/${route}`, { username, password });
      await refresh();
      return res.data;
    };

    return {
      ...status,
      isAdmin: status.role === adminRole,
      login: (username, password) => submit('login', username, password),
      setup: (username, password) => submit('setup', username, password),
      // Self-registration: the backend decides the role — the first account
      // ever becomes an admin, later ones are regular users.
      register: (username, password) => submit('register', username, password),
      logout: async () => {
        await api.post(`${basePath}/logout`);
        await refresh();
      },
      refresh,
    };
  }, [status, api, basePath, adminRole, refresh]);

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}
