/**
 * Web Notifications primitives — permission handling and a single toast.
 * What gets notified, and when, is the app's business; this module only knows
 * how to ask politely and how to pop one.
 */

// Conventional PWA icon paths; override per call via `options`.
const DEFAULT_ICONS = { icon: "/icon-192.png", badge: "/favicon-32.png" };

/**
 * Ensures notification permission is granted, requesting it if still undecided.
 * Returns the final permission string ("granted" | "denied" | "default" | "unsupported").
 */
export async function ensurePermission() {
  if (typeof Notification === "undefined") return "unsupported";
  if (Notification.permission === "default") {
    try {
      return await Notification.requestPermission();
    } catch {
      return Notification.permission;
    }
  }
  return Notification.permission;
}

/**
 * Shows a desktop toast now. Returns { ok, reason } so callers can give feedback.
 * reason is one of: "unsupported" | "denied" | "default" | "error".
 *
 * `tag` de-dupes: reusing a tag silently replaces the previous notification
 * rather than re-alerting, so pass a unique one when a repeat must be seen.
 */
export async function showDesktopNotification(title, body, tag, options) {
  const perm = await ensurePermission();
  if (perm !== "granted") return { ok: false, reason: perm === "unsupported" ? "unsupported" : perm };
  try {
    const n = new Notification(title, { body, tag, ...DEFAULT_ICONS, ...options });
    // Focus this tab if the user clicks the toast.
    n.onclick = () => { try { window.focus(); } catch { /* ignore */ } };
    return { ok: true };
  } catch (e) {
    return { ok: false, reason: "error", error: String(e) };
  }
}
