import '../styles/ui.css';

/**
 * Switch — on/off control for boolean settings.
 *
 * A real <button role="switch">, so it is reachable by Tab, toggles on
 * Space/Enter and announces its state to screen readers. Prefer this over a
 * pair of Enable/Disable buttons: the current state is visible at a glance.
 *
 * Props:
 *   checked    — boolean
 *   onChange   — (next: boolean) => void
 *   disabled   — boolean
 *   label      — accessible name (required when there's no visible <label>)
 *   describedBy — id of the element describing the setting
 */
export default function Switch({ checked = false, onChange, disabled, label, describedBy, size }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      aria-describedby={describedBy}
      disabled={disabled}
      className={`ui-switch${checked ? ' on' : ''}${size === 'sm' ? ' sm' : ''}`}
      onClick={() => onChange?.(!checked)}
    >
      <span className="ui-switch-thumb" />
    </button>
  );
}
